mapper.select:
select

from ujcms_page_region_snapshot t
where t.id_ = #{id,jdbcType=BIGINT}

select

from ujcms_page_region_snapshot t
where t.site_id_ = #{siteId,jdbcType=BIGINT}
  and t.page_ref_ = #{pageRef,jdbcType=VARCHAR}
  and t.region_name_ = #{regionName,jdbcType=VARCHAR}
  and t.scope_ = #{scope,jdbcType=VARCHAR}
order by t.id_ desc
